questionvariables.text:
wordlength1:rand([6,7,8]);
word1:if wordlength1 = 6 then rand([friday,family,silver,monday]) elseif wordlength1=7 then rand([departs,country,history,kitchen]) else rand([thousand,children,equation,champion]);
ta1:if wordlength1 = 6 then 6! elseif wordlength1 = 7 then 7! else 8!;

wordlength2:rand([6,7,8]);
word2:if wordlength2 = 6 then rand([twelve,thirty,future,africa]) elseif wordlength2=7 then rand([perfect,america,freedom,seventy]) else rand([fourteen,american,mountain,strength]);
letter2:if word2 = fourteen then "e" elseif word2 = american then "a" elseif word2 = mountain then "n" elseif word2 = strength then "t" elseif word2 = perfect then "e" elseif word2 = america then "a" elseif word2 = freedom then "e" elseif word2 = seventy then "e" elseif word2 = twelve then "e" elseif word2 = thirty then "t" elseif word2 = future then "u" else "a";
ta2:if wordlength2 = 6 then 6!/2 elseif wordlength2 = 7 then 7!/2 else 8!/2;

wordlength3:rand([6,7,8]);
word3:if wordlength3 = 6 then rand([eleven,canada,bubble,mirror]) elseif wordlength3=7 then rand([warrior,weekend,between,goggles]) else rand([business,syllable,virginia,envelope]);
letter3:if word3 = eleven then "e" elseif word3 = canada then "a" elseif word3 = bubble then "b" elseif word3 = mirror then "r" elseif word3 = warrior then "r" elseif word3 = weeked then "e" elseif word3 = between then "e" elseif word3 = goggles then "g" elseif word3 = business then "s" elseif word3 = syllable then "l" elseif word3 = virginia then "i" else "e";
ta3:if wordlength3 = 6 then 6!/6 elseif wordlength3 = 7 then 7!/6 else 8!/6;
